import{_ as e,o as a,c as r,ag as n}from"./chunks/framework.DTisvaUJ.js";const h=JSON.parse('{"title":"隐私","description":"说明Mutelink向外部发送及在本机保存的信息，包括识别、翻译、使用情况和问题报告。","frontmatter":{"description":"说明Mutelink向外部发送及在本机保存的信息，包括识别、翻译、使用情况和问题报告。","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/zh/about/privacy"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"zh_CN"}],["meta",{"property":"og:title","content":"隐私 | Mutelink"}],["meta",{"property":"og:description","content":"说明Mutelink向外部发送及在本机保存的信息，包括识别、翻译、使用情况和问题报告。"}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/zh/about/privacy"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"property":"og:image:width","content":"1920"}],["meta",{"property":"og:image:height","content":"1080"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"隐私 | Mutelink"}],["meta",{"name":"twitter:description","content":"说明Mutelink向外部发送及在本机保存的信息，包括识别、翻译、使用情况和问题报告。"}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/about/privacy"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/about/privacy"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/about/privacy"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/about/privacy"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/about/privacy"}]]},"headers":[],"relativePath":"zh/about/privacy.md","filePath":"zh/about/privacy.md"}'),i={name:"zh/about/privacy.md"};function o(l,t,s,u,d,p){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="プライバシー" tabindex="-1">隐私 <a class="header-anchor" href="#プライバシー" aria-label="Permalink to &quot;隐私 {#プライバシー}&quot;">​</a></h1><p>本页说明Mutelink会向外部发送的数据。</p><h2 id="外部に送られるデータ" tabindex="-1">发送到外部的数据 <a class="header-anchor" href="#外部に送られるデータ" aria-label="Permalink to &quot;发送到外部的数据 {#外部に送られるデータ}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>发送内容</th><th>接收方</th></tr></thead><tbody><tr><td>选择云端语音识别时</td><td>麦克风音频</td><td>Microsoft或Google</td></tr><tr><td>使用Azure Translator翻译时</td><td>待翻译文本</td><td>Microsoft（使用你自己的密钥）</td></tr><tr><td>听取对方语音时选择Google</td><td>对方的语音</td><td>Google</td></tr><tr><td>将对方发言显示到聊天框时</td><td>对方的发言及译文</td><td>VRChat（实例中的所有人可见）</td></tr><tr><td>允许发送使用情况时</td><td>匿名使用情况（如下）</td><td>作者运营的Cloudflare服务器</td></tr><tr><td>发送问题与建议时</td><td>填写的内容与所选附件（如下）</td><td>作者的Cloudflare服务器和Discord</td></tr><tr><td>下载和检查更新时</td><td>仅连接所需信息</td><td>各分发方</td></tr></tbody></table><p>以下功能完全在本机运行，不向外部发送数据。</p><ul><li>本地语音识别（Parakeet、Haas-ja、Qwen3-ASR、Whisper turbo）</li><li>语音合成（VOICEVOX、Irodori-TTS、Qwen3-TTS）</li><li>本地翻译（PLaMo、TranslateGemma）</li><li>VR键盘的假名汉字转换及拼音转换</li></ul><p>本地识别对方语音时，音频不会离开电脑，识别完成后立即丢弃，不保存。选择Google时，对方音频将发送至Google。请注意使用方式，例如事先告知对方。</p><p>VR中的对方语音及自己的聊天框面板仅自己可见，但直播软件直接采集VR视野时，面板也可能被拍到。</p><h2 id="利用状況の送信" tabindex="-1">使用情况报告 <a class="header-anchor" href="#利用状況の送信" aria-label="Permalink to &quot;使用情况报告 {#利用状況の送信}&quot;">​</a></h2><p>为改进Mutelink，<strong>仅在本人允许时</strong>每月发送一次匿名使用情况。快速设置结束时会询问；不允许则不发送。可随时在设置 &gt; 其他 &gt; 关于中更改并查看下次发送的内容。</p><ul><li><strong>发送内容</strong>：应用版本；OS、CPU、GPU、内存；启动、VR启动、各引擎识别/朗读/翻译次数、错误次数、VR输入操作和聊天框发送次数；各语言引擎、翻译优先级、输入方式、用途、是否修改按钮布局等设置；付费功能启用情况。</li><li><strong>不发送</strong>：发言内容、识别或输入的文字、声音音频、语尾内容、模板、排除词、历史记录、设备名称、API密钥、注册声音名称、真实姓名或联系方式。</li><li><strong>接收方</strong>：作者运营的Cloudflare服务器，不保存IP地址。</li><li><strong>目的</strong>：了解功能使用情况和电脑配置，决定改进优先级。</li><li><strong>匿名ID</strong>：应用生成的随机编号，不关联个人，可随时在设置中重新生成。</li></ul><h2 id="不具合・要望の送信" tabindex="-1">发送问题与建议 <a class="header-anchor" href="#不具合・要望の送信" aria-label="Permalink to &quot;发送问题与建议 {#不具合・要望の送信}&quot;">​</a></h2><p>可在设置 &gt; 其他 &gt; 关于 &gt; 发送问题与建议中匿名联系作者。<strong>仅点击发送按钮时</strong>才发送，发送前可确认具体内容。</p><ul><li><strong>必发内容</strong>：类型（问题、建议、其他）及填写的文字。需要回复时可自愿填写联系方式。</li><li><strong>仅选择时发送</strong>：版本和电脑信息（OS、CPU、内存、GPU、VRAM）、日志及一张图片。日志和图片默认关闭。</li><li><strong>日志排除内容</strong>：发送时删除包含发言或输入文本的行，并隐藏路径中的用户名。</li><li><strong>图片</strong>：通知、姓名、文件名等屏幕内容会原样出现。图片仅通知至作者的Discord，不在服务器保存。</li><li><strong>处理方式</strong>：不保存IP地址，不与使用情况报告关联。请勿填写姓名、地址等个人信息。</li></ul><h2 id="pcの中に保存されるデータ" tabindex="-1">本机保存的数据 <a class="header-anchor" href="#pcの中に保存されるデータ" aria-label="Permalink to &quot;本机保存的数据 {#pcの中に保存されるデータ}&quot;">​</a></h2><p>下载的模型和角色、注册声音的特征（不保存原始录音）、VR背景图、许可证、设置及翻译字符数记录保存在本机。</p><p>全新安装的数据位于<code>%LOCALAPPDATA%\\com.utyujinn.mutelink</code>。从旧版升级的用户，部分数据可能仍在安装目录中。</p><p>Azure Translator密钥仅保存在本机设置中。</p>',18)])])}const c=e(i,[["render",o]]);export{h as __pageData,c as default};
